22	 */
23	export interface SeatbeltArgsOptions {
24	  /** The primary workspace path to allow access to. */
25	  workspace: string;
26	  /** Additional paths to allow access to. */
27	  allowedPaths?: string[];
28	  /** Absolute paths to explicitly deny read/write access to (overrides allowlists). */
