38	/**
39	 * Resolves symlinks for a given path to prevent sandbox escapes.
40	 * If a file does not exist (ENOENT), it recursively resolves the parent directory.
41	 * Other errors (e.g. EACCES) are re-thrown.
42	 */
43	function tryRealpath(p: string): string {
44	  try {
45	    return fs.realpathSync(p);
46	  } catch (e) {
47	    if (e instanceof Error && 'code' in e && e.code === 'ENOENT') {
48	      const parentDir = path.dirname(p);
49	      if (parentDir === p) {
50	        return p;
51	      }
52	      return path.join(tryRealpath(parentDir), path.basename(p));
53	    }
54	    throw e;
55	  }
56	}
