58	/**
59	 * Builds the arguments array for sandbox-exec using a strict allowlist profile.
60	 * It relies on parameters passed to sandbox-exec via the -D flag to avoid
61	 * string interpolation vulnerabilities, and normalizes paths against symlink escapes.
62	 *
63	 * Returns arguments up to the end of sandbox-exec configuration (e.g. ['-p', '<profile>', '-D', ...])
64	 * Does not include the final '--' separator or the command to run.
65	 */
66	export function buildSeatbeltArgs(options: SeatbeltArgsOptions): string[] {
67	  let profile = BASE_SEATBELT_PROFILE + '\n';
68	  const args: string[] = [];
69	
70	  const workspacePath = tryRealpath(options.workspace);
71	  args.push('-D', `WORKSPACE=${workspacePath}`);
72	  args.push('-D', `WORKSPACE_RAW=${options.workspace}`);
73	  profile += `(allow file-read* (subpath (param "WORKSPACE_RAW")))\n`;
74	  if (options.workspaceWrite) {
75	    profile += `(allow file-write* (subpath (param "WORKSPACE_RAW")))\n`;
76	  }
77	
78	  if (options.workspaceWrite) {
79	    profile += `(allow file-write* (subpath (param "WORKSPACE")))\n`;
80	  }
81	
82	  // Add explicit deny rules for governance files in the workspace.
83	  // These are added after the workspace allow rule to ensure they take precedence
84	  // (Seatbelt evaluates rules in order, later rules win for same path).
85	  for (let i = 0; i < GOVERNANCE_FILES.length; i++) {
86	    const governanceFile = path.join(workspacePath, GOVERNANCE_FILES[i].path);
87	    const realGovernanceFile = tryRealpath(governanceFile);
88	
89	    // Determine if it should be treated as a directory (subpath) or a file (literal).
90	    // .git is generally a directory, while ignore files are literals.
91	    let isDirectory = GOVERNANCE_FILES[i].isDirectory;
92	    try {
93	      if (fs.existsSync(realGovernanceFile)) {
94	        isDirectory = fs.lstatSync(realGovernanceFile).isDirectory();
95	      }
96	    } catch {
97	      // Ignore errors, use default guess
98	    }
99	
100	    const ruleType = isDirectory ? 'subpath' : 'literal';
101	
102	    args.push('-D', `GOVERNANCE_FILE_${i}=${governanceFile}`);
103	    profile += `(deny file-write* (${ruleType} (param "GOVERNANCE_FILE_${i}")))\n`;
104	
105	    if (realGovernanceFile !== governanceFile) {
106	      args.push('-D', `REAL_GOVERNANCE_FILE_${i}=${realGovernanceFile}`);
107	      profile += `(deny file-write* (${ruleType} (param "REAL_GOVERNANCE_FILE_${i}")))\n`;
108	    }
109	  }
110	
111	  // Auto-detect and support git worktrees by granting read and write access to the underlying git directory
112	  try {
113	    const gitPath = path.join(workspacePath, '.git');
114	    const gitStat = fs.lstatSync(gitPath);
115	    if (gitStat.isFile()) {
116	      const gitContent = fs.readFileSync(gitPath, 'utf8');
117	      const match = gitContent.match(/^gitdir:\s*(.+)$/m);
118	      if (match && match[1]) {
119	        let worktreeGitDir = match[1].trim();
120	        if (!path.isAbsolute(worktreeGitDir)) {
121	          worktreeGitDir = path.resolve(workspacePath, worktreeGitDir);
122	        }
123	        const resolvedWorktreeGitDir = tryRealpath(worktreeGitDir);
124	
125	        // Grant write access to the worktree's specific .git directory
126	        args.push('-D', `WORKTREE_GIT_DIR=${resolvedWorktreeGitDir}`);
127	        profile += `(allow file-read* file-write* (subpath (param "WORKTREE_GIT_DIR")))\n`;
128	
129	        // Grant write access to the main repository's .git directory (objects, refs, etc. are shared)
130	        // resolvedWorktreeGitDir is usually like: /path/to/main-repo/.git/worktrees/worktree-name
131	        const mainGitDir = tryRealpath(
132	          path.dirname(path.dirname(resolvedWorktreeGitDir)),
133	        );
134	        if (mainGitDir && mainGitDir.endsWith('.git')) {
135	          args.push('-D', `MAIN_GIT_DIR=${mainGitDir}`);
136	          profile += `(allow file-read* file-write* (subpath (param "MAIN_GIT_DIR")))\n`;
137	        }
138	      }
139	    }
140	  } catch (_e) {
141	    // Ignore if .git doesn't exist, isn't readable, etc.
142	  }
