144	  const tmpPath = tryRealpath(os.tmpdir());
145	  args.push('-D', `TMPDIR=${tmpPath}`);
146	
147	  const nodeRootPath = tryRealpath(
148	    path.dirname(path.dirname(process.execPath)),
149	  );
150	  args.push('-D', `NODE_ROOT=${nodeRootPath}`);
151	  profile += `(allow file-read* (subpath (param "NODE_ROOT")))\n`;
152	
153	  // Add PATH directories as read-only to support nvm, homebrew, etc.
154	  if (process.env['PATH']) {
155	    const paths = process.env['PATH'].split(':');
156	    let pathIndex = 0;
157	    const addedPaths = new Set();
158	
159	    for (const p of paths) {
160	      if (!p.trim()) continue;
161	      try {
162	        let resolved = tryRealpath(p);
163	
164	        // If this is a 'bin' directory (like /usr/local/bin or homebrew/bin),
165	        // also grant read access to its parent directory so that symlinked
166	        // assets (like Cellar or libexec) can be read.
167	        if (resolved.endsWith('/bin')) {
168	          resolved = path.dirname(resolved);
169	        }
170	
171	        if (!addedPaths.has(resolved)) {
172	          addedPaths.add(resolved);
173	          args.push('-D', `SYS_PATH_${pathIndex}=${resolved}`);
174	          profile += `(allow file-read* (subpath (param "SYS_PATH_${pathIndex}")))\n`;
175	          pathIndex++;
176	        }
177	      } catch (_e) {
178	        // Ignore paths that do not exist or are inaccessible
179	      }
180	    }
181	  }
