183	  // Handle allowedPaths
184	  const allowedPaths = sanitizePaths(options.allowedPaths) || [];
185	  for (let i = 0; i < allowedPaths.length; i++) {
186	    const allowedPath = tryRealpath(allowedPaths[i]);
187	    args.push('-D', `ALLOWED_PATH_${i}=${allowedPath}`);
