7	import fs from 'node:fs';
8	import { join, dirname, normalize } from 'node:path';
9	import os from 'node:os';
10	import {
11	  type SandboxManager,
12	  type GlobalSandboxOptions,
13	  type SandboxRequest,
14	  type SandboxedCommand,
15	  GOVERNANCE_FILES,
16	  sanitizePaths,
17	} from '../../services/sandboxManager.js';
18	import {
19	  sanitizeEnvironment,
20	  getSecureSanitizationConfig,
21	} from '../../services/environmentSanitization.js';
22	
23	let cachedBpfPath: string | undefined;
24	
25	function getSeccompBpfPath(): string {
26	  if (cachedBpfPath) return cachedBpfPath;
27	
28	  const arch = os.arch();
29	  let AUDIT_ARCH: number;
30	  let SYS_ptrace: number;
31	
32	  if (arch === 'x64') {
33	    AUDIT_ARCH = 0xc000003e; // AUDIT_ARCH_X86_64
34	    SYS_ptrace = 101;
35	  } else if (arch === 'arm64') {
36	    AUDIT_ARCH = 0xc00000b7; // AUDIT_ARCH_AARCH64
37	    SYS_ptrace = 117;
38	  } else if (arch === 'arm') {
39	    AUDIT_ARCH = 0x40000028; // AUDIT_ARCH_ARM
40	    SYS_ptrace = 26;
41	  } else if (arch === 'ia32') {
42	    AUDIT_ARCH = 0x40000003; // AUDIT_ARCH_I386
43	    SYS_ptrace = 26;
44	  } else {
45	    throw new Error(`Unsupported architecture for seccomp filter: ${arch}`);
46	  }
47	
48	  const EPERM = 1;
49	  const SECCOMP_RET_KILL_PROCESS = 0x80000000;
50	  const SECCOMP_RET_ERRNO = 0x00050000;
51	  const SECCOMP_RET_ALLOW = 0x7fff0000;
52	
53	  const instructions = [
54	    { code: 0x20, jt: 0, jf: 0, k: 4 }, // Load arch
55	    { code: 0x15, jt: 1, jf: 0, k: AUDIT_ARCH }, // Jump to kill if arch != native arch
56	    { code: 0x06, jt: 0, jf: 0, k: SECCOMP_RET_KILL_PROCESS }, // Kill
57	
58	    { code: 0x20, jt: 0, jf: 0, k: 0 }, // Load nr
59	    { code: 0x15, jt: 0, jf: 1, k: SYS_ptrace }, // If ptrace, jump to ERRNO
60	    { code: 0x06, jt: 0, jf: 0, k: SECCOMP_RET_ERRNO | EPERM }, // ERRNO
61	
62	    { code: 0x06, jt: 0, jf: 0, k: SECCOMP_RET_ALLOW }, // Allow
63	  ];
64	
65	  const buf = Buffer.alloc(8 * instructions.length);
66	  for (let i = 0; i < instructions.length; i++) {
67	    const inst = instructions[i];
68	    const offset = i * 8;
69	    buf.writeUInt16LE(inst.code, offset);
70	    buf.writeUInt8(inst.jt, offset + 2);
71	    buf.writeUInt8(inst.jf, offset + 3);
72	    buf.writeUInt32LE(inst.k, offset + 4);
73	  }
74	
75	  const bpfPath = join(os.tmpdir(), `gemini-cli-seccomp-${process.pid}.bpf`);
76	  fs.writeFileSync(bpfPath, buf);
77	  cachedBpfPath = bpfPath;
78	  return bpfPath;
79	}
