81	/**
82	 * Ensures a file or directory exists.
83	 */
84	function touch(filePath: string, isDirectory: boolean) {
85	  try {
86	    // If it exists (even as a broken symlink), do nothing
87	    if (fs.lstatSync(filePath)) return;
88	  } catch {
89	    // Ignore ENOENT
90	  }
91	
92	  if (isDirectory) {
93	    fs.mkdirSync(filePath, { recursive: true });
94	  } else {
95	    fs.mkdirSync(dirname(filePath), { recursive: true });
96	    fs.closeSync(fs.openSync(filePath, 'a'));
97	  }
98	}
