31	export interface MacOsSandboxOptions extends GlobalSandboxOptions {
32	  /** Optional base sanitization config. */
33	  sanitizationConfig?: EnvironmentSanitizationConfig;
34	  /** The current sandbox mode behavior from config. */
35	  modeConfig?: {
36	    readonly?: boolean;
37	    network?: boolean;
38	    approvedTools?: string[];
39	    allowOverrides?: boolean;
40	  };
41	  /** The policy manager for persistent approvals. */
42	  policyManager?: SandboxPolicyManager;
43	}
