45	/**
46	 * A SandboxManager implementation for macOS that uses Seatbelt.
47	 */
48	export class MacOsSandboxManager implements SandboxManager {
49	  constructor(private readonly options: MacOsSandboxOptions) {}
50	
51	  private async isStrictlyApproved(req: SandboxRequest): Promise<boolean> {
52	    const approvedTools = this.options.modeConfig?.approvedTools;
53	    if (!approvedTools || approvedTools.length === 0) {
54	      return false;
55	    }
56	
57	    await initializeShellParsers();
58	
59	    const fullCmd = [req.command, ...req.args].join(' ');
60	    const stripped = stripShellWrapper(fullCmd);
61	
62	    const roots = getCommandRoots(stripped);
63	    if (roots.length === 0) return false;
64	
65	    const allRootsApproved = roots.every((root) =>
66	      approvedTools.includes(root),
67	    );
68	    if (allRootsApproved) {
69	      return true;
70	    }
71	
72	    const pipelineCommands = splitCommands(stripped);
73	    if (pipelineCommands.length === 0) return false;
74	
75	    // For safety, every command in the pipeline must be considered safe.
76	    for (const cmdString of pipelineCommands) {
77	      const parsedArgs = shellParse(cmdString).map(String);
78	      if (!isKnownSafeCommand(parsedArgs)) {
79	        return false;
80	      }
81	    }
82	
83	    return true;
84	  }
85	
86	  private async getCommandName(req: SandboxRequest): Promise<string> {
87	    await initializeShellParsers();
88	    const fullCmd = [req.command, ...req.args].join(' ');
89	    const stripped = stripShellWrapper(fullCmd);
90	    const roots = getCommandRoots(stripped).filter(
91	      (r) => r !== 'shopt' && r !== 'set',
92	    );
93	    if (roots.length > 0) {
94	      return roots[0];
95	    }
96	    return path.basename(req.command);
97	  }
98	
99	  async prepareCommand(req: SandboxRequest): Promise<SandboxedCommand> {
100	    await initializeShellParsers();
101	    const sanitizationConfig = getSecureSanitizationConfig(
102	      req.policy?.sanitizationConfig,
103	    );
104	
105	    const sanitizedEnv = sanitizeEnvironment(req.env, sanitizationConfig);
106	
107	    const isReadonlyMode = this.options.modeConfig?.readonly ?? true;
108	    const allowOverrides = this.options.modeConfig?.allowOverrides ?? true;
109	
110	    // Reject override attempts in plan mode
111	    if (!allowOverrides && req.policy?.additionalPermissions) {
112	      const perms = req.policy.additionalPermissions;
113	      if (
114	        perms.network ||
115	        (perms.fileSystem?.write && perms.fileSystem.write.length > 0)
116	      ) {
117	        throw new Error(
118	          'Sandbox request rejected: Cannot override readonly/network restrictions in Plan mode.',
119	        );
120	      }
121	    }
122	
123	    // If not in readonly mode OR it's a strictly approved pipeline, allow workspace writes
124	    const isApproved = allowOverrides
125	      ? await this.isStrictlyApproved(req)
126	      : false;
127	
128	    const workspaceWrite = !isReadonlyMode || isApproved;
129	    const networkAccess =
130	      this.options.modeConfig?.network ?? req.policy?.networkAccess ?? false;
131	
132	    // Fetch persistent approvals for this command
133	    const commandName = await this.getCommandName(req);
134	    const persistentPermissions = allowOverrides
135	      ? this.options.policyManager?.getCommandPermissions(commandName)
136	      : undefined;
137	
138	    // Merge all permissions
139	    const mergedAdditional: SandboxPermissions = {
140	      fileSystem: {
141	        read: [
142	          ...(persistentPermissions?.fileSystem?.read ?? []),
143	          ...(req.policy?.additionalPermissions?.fileSystem?.read ?? []),
144	        ],
145	        write: [
146	          ...(persistentPermissions?.fileSystem?.write ?? []),
147	          ...(req.policy?.additionalPermissions?.fileSystem?.write ?? []),
148	        ],
149	      },
150	      network:
151	        networkAccess ||
152	        persistentPermissions?.network ||
153	        req.policy?.additionalPermissions?.network ||
154	        false,
155	    };
156	
157	    const sandboxArgs = buildSeatbeltArgs({
158	      workspace: this.options.workspace,
159	      allowedPaths: [...(req.policy?.allowedPaths || [])],
160	      forbiddenPaths: req.policy?.forbiddenPaths,
161	      networkAccess: mergedAdditional.network,
162	      workspaceWrite,
163	      additionalPermissions: mergedAdditional,
164	    });
165	
166	    return {
167	      program: '/usr/bin/sandbox-exec',
168	      args: [...sandboxArgs, '--', req.command, ...req.args],
169	      env: sanitizedEnv,
170	      cwd: req.cwd,
171	    };
172	  }
173	}
